class Asteroid {
    constructor() {
      // Spawn on a random edge
      const edge = Math.floor(Math.random() * 4);
      const margin = 10;
      let x, y, vx, vy;
      const speed = ASTEROID_MIN_SPEED + Math.random() * (ASTEROID_MAX_SPEED - ASTEROID_MIN_SPEED);
      switch (edge) {
        case 0: // top
          x = Math.random() * canvas.width;
          y = -margin;
          break;
        case 1: // right
          x = canvas.width + margin;
          y = Math.random() * canvas.height;
          break;
        case 2: // bottom
          x = Math.random() * canvas.width;
          y = canvas.height + margin;
          break;
        case 3: // left
          x = -margin;
          y = Math.random() * canvas.height;
          break;
      }
      // Aim roughly toward the planet center with a slight random offset for curvature
      const targetX = canvas.width / 2 + (Math.random() - 0.5) * 80;
      const targetY = canvas.height / 2 + (Math.random() - 0.5) * 80;
      const dx = targetX - x;
      const dy = targetY - y;
      const len = Math.hypot(dx, dy);
      vx = (dx / len) * speed;
      vy = (dy / len) * speed;
      this.x = x;
      this.y = y;
      this.vx = vx;
      this.vy = vy;
      this.radius = 8 + Math.random() * 6;
    }
    update(dt) {
      this.x += this.vx * dt;
      this.y += this.vy * dt;
    }
    draw() {
      ctx.fillStyle = '#888';
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
      ctx.fill();
    }
  }

